SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
IF DB_NAME() <> 'CQGlobalSGDW' OR UPPER(@@SERVERNAME) NOT IN ('<DEV_DWH_SERVER>') BEGIN RAISERROR('Wrong database or server: only the DEV DWH (<DEV_DWH_SERVER> / CQGlobalSGDW) is allowed; nothing below is run (SET NOEXEC ON).', 16, 1); SET NOEXEC ON; END
GO
/*
T3 - Load the pipeline -> table registry (docs/T3_mapping_proposal.csv, 33 rows: 32 generated by T3 plus
Integration.MultipleAccounts_Staging, hand-added after the T3 proposal on user confirmation, D-030, and also
appended to that CSV so a regenerate keeps it) and the
static table list. Idempotent: inserts only rows that are missing; never updates or deletes.
A re-assigned pipeline (table moved to another pipeline) is NOT handled: delete the old row by hand first,
otherwise the table ends up in two pipelines. The last query lists registry rows that are not in this CSV
(hand-added or stale) so they are visible after every load.
Mapping confirmed by the user in D-025. Requires T1_mapping_schema.sql. Dev DWH.
*/
SET NOCOUNT ON;
SELECT * INTO #csv FROM (VALUES
    (N'CQGlobalSGDW: NovaDailyETL', N'Dimension', N'Account', N'proc Integration.MigrateStagedNovaAccountData is_updated=1 (only writer found); Agent job NovaDailyETL step 2 runs SSIS DailyNovaVolumeLoad.dtsx, task "Migrate Staged Nova Account Data"; DW_NovaLineage "[Dimension].[Account]"'),
