INSERT Integration.Tableau_PipelineTable (PipelineName, SchemaName, TableName, Evidence, ConfirmedBy)
SELECT s.PipelineName, s.SchemaName, s.TableName, s.Evidence, N'user (via PM session)'
FROM #csv AS s
WHERE NOT EXISTS (SELECT 1 FROM Integration.Tableau_PipelineTable t
                  WHERE t.SchemaName = s.SchemaName AND t.TableName = s.TableName AND t.PipelineName = s.PipelineName);

IF NOT EXISTS (SELECT 1 FROM Integration.Tableau_StaticTable WHERE SchemaName = N'dbo' AND TableName = N'SalesChannel_Excel')
    INSERT Integration.Tableau_StaticTable (SchemaName, TableName, Reason, SetBy)
    VALUES (N'dbo', N'SalesChannel_Excel', N'Deprecated, no freshness check (D-025 item 7)', N'user (via PM session)');

-- Report: registry rows not in the CSV (expected: none)
SELECT t.PipelineName, t.SchemaName, t.TableName, t.ConfirmedBy AS NotInCsv
FROM Integration.Tableau_PipelineTable t
WHERE NOT EXISTS (SELECT 1 FROM #csv s WHERE s.SchemaName = t.SchemaName AND s.TableName = t.TableName AND s.PipelineName = t.PipelineName);
SELECT COUNT(*) AS RegistryRows FROM Integration.Tableau_PipelineTable;
GO
SET NOEXEC OFF;
